-- KO-225 group 5 exact duplicate translation batch 2

update public.content_variants set body = $json${"text":"Doni borrowed IDR 2,000,000 through a loan with 10% interest per month. After a month, he must return Rp. 2,200,000. Interest is the cost of borrowing money."}$json$::jsonb where id = '0cd547fb-3e0a-4f60-97dc-dc2b2c9c91f6';
update public.content_variants set body = $json${"text":"Product-based MLMs make money from selling goods. Pyramids make money primarily from recruiting new members. When recruits run out, the pyramid collapses."}$json$::jsonb where id = '0d9cd1b9-e67d-47b1-b34f-4e1ada988c61';
update public.content_variants set body = $json${"text":"Doni received deposit interest of IDR 500,000 and stock dividends of IDR 1,000,000. The government imposes taxes on this income. After taxes, the money he actually received was less than the gross figure."}$json$::jsonb where id = '0e2e3139-b003-4eda-a09f-bc48c7ed0074';
update public.content_variants set body = $json${"text":"A financial plan includes goals, emergency funds, debt, protection, and investment steps. Plans help us make decisions that align with long-term goals."}$json$::jsonb where id = '102af6c8-55c1-46f0-aa4f-1591d5613917';
update public.content_variants set body = $json${"text":"Macro indicators such as the BI Rate, inflation and exchange rates influence the overall economy and impact investment and purchasing power."}$json$::jsonb where id = '111850a1-1d9c-4d4d-b205-7fc1fde2cd41';
update public.content_variants set body = $json${"text":"An SME in Bandung separates operational accounts and the owner's personal accounts. The owner takes a fixed salary of IDR 3 million per month, so that business finances are not mixed with personal expenses.","source_ids":["ad0e8258-4e0a-4378-b257-4fd3628c6953"]}$json$::jsonb where id = '113bc537-eb0b-465d-96f9-3ab54a18c0ed';
update public.content_variants set body = $json${"text":"Budi is an online motorcycle taxi driver with a variable income. The cellphone was damaged and the repair cost was IDR 3,000,000. Because Budi has an emergency fund of IDR 5,000,000 in a separate savings account, he can repair his cellphone without borrowing from the loan application."}$json$::jsonb where id = '11539219-0b5e-4644-8964-73c1fec839a3';
update public.content_variants set body = $json${"text":"SIPF (Securities Investor Protection Fund) protects investors if a securities company goes bankrupt. Investor funds are held in stock accounts separate from securities company assets.","source_ids":["5fa2799e-2b92-46e8-b68a-c9d64847410c"]}$json$::jsonb where id = '1276d418-6775-4bb4-a925-8a44c740cf40';
update public.content_variants set body = $json${"text":"The rupiah exchange rate against the US dollar affects the prices of imported goods such as oil and medicine. If the rupiah weakens, the prices of these goods rise and trigger inflation.","source_ids":["8da2696d-9836-4a3b-9524-da7e2b823c60"]}$json$::jsonb where id = '14a38cc0-e8c9-44ca-90dc-20c144666264';
update public.content_variants set body = $json${"text":"Budi's salary is IDR 3,000,000. Needs IDR 1,500,000 (50%), desires IDR 900,000 (30%), savings/debt IDR 600,000 (20%). If his needs increase because of college costs, Budi must temporarily reduce his desires, not reduce his savings."}$json$::jsonb where id = '14dfd850-27ba-4b42-991b-ca7e803bc79f';

